const output = $json.output || "";

// Extract the markdown table from AI Agent output
const lines = output.split("\n");

const tableLines = lines.filter(line => line.includes("|"));

if (tableLines.length < 2) {
  return [
    {
      json: {
        error: "No table found in AI Agent output",
        originalOutput: output
      }
    }
  ];
}

// Remove header separator row
const dataLines = tableLines.filter(
  line => !line.match(/^\s*\|?\s*:?-+:?\s*\|/)
);

// Get table header
const headers = dataLines[0]
  .split("|")
  .map(item => item.trim())
  .filter(item => item !== "");

// Convert table rows into objects
const tableData = [];

for (let i = 1; i < dataLines.length; i++) {

  const values = dataLines[i]
    .split("|")
    .map(item => item.trim())
    .filter(item => item !== "");

  if (values.length === headers.length) {

    const row = {};

    headers.forEach((header, index) => {
      row[header] = values[index];
    });

    tableData.push(row);
  }
}

// Return each week as a separate n8n item
return tableData.map(row => ({
  json: row
}));

